const std = @import("std");
const expectEqual = std.testing.expectEqual;

const AppOperation = enum(u8) { add, backspace, reset, query, add_again };

fn choose_app_operation(smith: *std.testing.Smith) AppOperation {
    return smith.valueWeighted(AppOperation, &.{
        .value(AppOperation, .add, 64),
        .value(AppOperation, .backspace, 12),
        .value(AppOperation, .reset, 4),
        .value(AppOperation, .query, 2),
        .value(AppOperation, .add_again, 18),
    });
}

fn choose_character(smith: *std.testing.Smith) u8 {
    return smith.valueWeighted(u8, &.{
        .value(u8, 'A', 8),
        .value(u8, 'a', 8),
        .rangeAtMost(u8, 'A', 'Z', 1),
        .rangeAtMost(u8, 'a', 'z', 1),
    });
}

// Mirror of FuzzHarness.encode_draws: one u64 little-endian per draw.
fn encode_draws(comptime draws: []const u64) []const u8 {
    const Encoded = struct {
        const bytes: [draws.len * 8]u8 = build: {
            var buffer: [draws.len * 8]u8 = undefined;
            for (draws, 0..) |draw, index| {
                std.mem.writeInt(u64, buffer[index * 8 ..][0..8], draw, .little);
            }
            break :build buffer;
        };
    };
    return &Encoded.bytes;
}

test "probe app-flow corpus decodes to the intended draws" {
    // 'qunf', backspace, 's' — the QU regression sequence.
    const entry = encode_draws(&.{
        6,
        @intFromEnum(AppOperation.add), 'q',
        @intFromEnum(AppOperation.add), 'u',
        @intFromEnum(AppOperation.add), 'n',
        @intFromEnum(AppOperation.add), 'f',
        @intFromEnum(AppOperation.backspace),
        @intFromEnum(AppOperation.add), 's',
    });

    var smith: std.testing.Smith = .{ .in = entry };

    const operation_count = smith.valueRangeAtMost(u8, 0, 160);
    try expectEqual(6, operation_count);

    const expected_characters = "qunf";
    for (expected_characters) |expected| {
        try expectEqual(AppOperation.add, choose_app_operation(&smith));
        try expectEqual(expected, choose_character(&smith));
    }
    try expectEqual(AppOperation.backspace, choose_app_operation(&smith));
    try expectEqual(AppOperation.add, choose_app_operation(&smith));
    try expectEqual(@as(u8, 's'), choose_character(&smith));
    try expectEqual(0, smith.in.?.len);
}

